package app.streamnest;
import android.content.*;import java.util.*;import org.json.*;
/** Explicit watched preferences; never writes playback positions. False entries are sync tombstones. */
final class ManualWatched {
 static JSONObject clean(JSONObject input)throws Exception{Map<String,JSONObject> found=new HashMap<>();if(input!=null)for(Iterator<String> it=input.keys();it.hasNext();){String id=it.next();JSONObject r=input.optJSONObject(id);if(!id.matches("tt[0-9]+")||r==null||!(r.opt("watched") instanceof Boolean)||!WatchSyncCrypto.integer(r,"updatedAt")||r.optLong("updatedAt")<1||r.optLong("updatedAt")>System.currentTimeMillis()+86400000)continue;JSONObject t=r.optJSONObject("title");if(t==null)continue;JSONObject m=HomeSync.metadata(t,t.optString("kind"));if(m!=null&&id.equals(m.optString("imdb")))found.put(id,new JSONObject().put("watched",r.getBoolean("watched")).put("updatedAt",r.getLong("updatedAt")).put("title",m).put("whole",r.optBoolean("whole")));}List<String> keys=new ArrayList<>(found.keySet());keys.sort((a,b)->{int c=Long.compare(found.get(b).optLong("updatedAt"),found.get(a).optLong("updatedAt"));return c!=0?c:a.compareTo(b);});JSONObject out=new JSONObject();for(String id:keys.subList(0,Math.min(500,keys.size()))){out.put(id,found.get(id));if(out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>90000){out.remove(id);break;}}return out;}
 static JSONObject merge(JSONObject a,JSONObject b)throws Exception{JSONObject out=clean(a),incoming=clean(b);for(Iterator<String> it=incoming.keys();it.hasNext();){String id=it.next();JSONObject r=incoming.getJSONObject(id),old=out.optJSONObject(id);if(old==null||r.getLong("updatedAt")>old.getLong("updatedAt")||r.getLong("updatedAt")==old.getLong("updatedAt")&&(!r.getBoolean("watched")&&old.getBoolean("watched")||r.getBoolean("watched")==old.getBoolean("watched")&&r.optBoolean("whole")&&!old.optBoolean("whole")))out.put(id,r);}return clean(out);}
 static String signature(JSONObject rows)throws Exception{if(rows.length()==0)return "";List<String> ids=new ArrayList<>();for(Iterator<String> it=rows.keys();it.hasNext();)ids.add(it.next());Collections.sort(ids);JSONArray a=new JSONArray();for(String id:ids){JSONObject r=rows.getJSONObject(id);JSONArray item=new JSONArray().put(id).put(r.getBoolean("watched")).put(r.getLong("updatedAt"));if(r.optBoolean("whole"))item.put(true);a.put(item);}return WatchSyncCrypto.hex(java.security.MessageDigest.getInstance("SHA-256").digest(a.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 static JSONObject records(Context c)throws Exception{return clean(new JSONObject(c.getSharedPreferences("manual-watched",0).getString("records","{}")));}
 static synchronized void store(Context c,JSONObject rows)throws Exception{String data=clean(rows).toString();SharedPreferences p=c.getSharedPreferences("manual-watched",0);if(!data.equals(p.getString("records","{}"))){p.edit().putString("records",data).commit();HomeLibrary.revision++;}}
 static synchronized void set(Context c,Catalog.Title t,boolean watched)throws Exception{JSONObject rows=records(c),m=HomeSync.metadata(t.raw,t.kind);if(m==null)return;long played=0;JSONObject history=WatchProgress.records(c);for(Iterator<String> it=history.keys();it.hasNext();){String key=it.next();if(key.split(":")[1].equals(t.id))played=Math.max(played,history.getJSONObject(key).optLong("updatedAt"));}long old=rows.optJSONObject(t.id)==null?0:rows.getJSONObject(t.id).optLong("updatedAt");rows.put(t.id,new JSONObject().put("watched",watched).put("updatedAt",Math.max(System.currentTimeMillis(),Math.max(old+1,played+1))).put("title",m).put("whole",true));store(c,rows);HomeLibrary.remember(c,t);WatchSync.request(c,true);}
 static boolean isWatched(Context c,String id){try{JSONObject r=records(c).optJSONObject(id);return r!=null&&r.optBoolean("watched")&&r.optBoolean("whole");}catch(Exception e){return false;}}
 static void sync(Context c,String pairing)throws Exception{String derived=WatchSyncCrypto.manualCode(pairing),auth=WatchSyncCrypto.auth(derived),endpoint=WatchSync.endpoint(c);for(int n=0;n<3;n++){if(!pairing.equals(WatchSync.code(c)))return;JSONObject remote=WatchSync.call(endpoint,"GET",auth,null,0);if(!pairing.equals(WatchSync.code(c)))return;JSONObject incoming=remote.isNull("payload")?new JSONObject():WatchSyncCrypto.openDocument(derived,remote.getJSONObject("payload")),next=merge(records(c),incoming);JSONObject response=WatchSync.call(endpoint,"PUT",auth,WatchSyncCrypto.seal(derived,next),remote.getLong("revision"));if(!pairing.equals(WatchSync.code(c)))return;if(!response.optBoolean("conflict")){store(c,merge(records(c),next));return;}}throw new java.io.IOException("Watched selections changed; retry shortly");}
}
